import sys

def main():
    line = sys.stdin.readline()
    if not line:
        return
    parts = line.split()
    n = int(parts[0])
    k = int(parts[1])

    def ask(c):
        print(f"? {c}")
        sys.stdout.flush()
        resp = sys.stdin.readline().strip()
        if resp == 'E':
            sys.exit(0)
        return resp == 'Y'

    def reset():
        print("R")
        sys.stdout.flush()

    distinct_count = 0
    i = 0
    while i < n:
        reset()
        found_new = False
        j = i
        while j < n and j - i < k:
            if ask(j + 1):
                pass
            else:
                distinct_count += 1
                found_new = True
            j += 1

        if not found_new:
            break

        if j >= n:
            break

        step = k // 2
        while j < n:
            reset()
            block_found = False
            for t in range(i, min(i + k, j)):
                if ask(t + 1):
                    pass
                else:
                    block_found = True

            if not block_found:
                break

            new_j = j
            while new_j < n and new_j - i < k:
                if ask(new_j + 1):
                    pass
                else:
                    distinct_count += 1
                    block_found = True
                new_j += 1

            if not block_found:
                break

            j = new_j
            if j >= n:
                break

        if j >= n:
            break

    print(f"! {distinct_count}")
    sys.stdout.flush()

if __name__ == "__main__":
    main()
